# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'

# The number of failures allowed before the game is lost.
MAX_FAILURES = 9


class Hangman:
    """A hangman game written in a functional reactive style.

    Instead of mutating a bunch of state in response to each guess,
    the game is modeled as a stream of guess events, and every
    observable (status, remaining guesses, masked word) is a pure
    derivation from that stream.
    """

    def __init__(self, word):
        self.word = word
        # The input signal: the full history of guess events.
        self._guesses = []

    # ------------------------------------------------------------------
    # Derived signals: pure functions of the guess history.
    # ------------------------------------------------------------------

    @property
    def _guessed(self):
        """The set of letters that have been revealed (correct guesses)."""
        return set(ch for ch in self._guesses if ch in self.word)

    @property
    def _failures(self):
        """Number of failed guesses: wrong letters, or repeats of a
        letter that was already revealed."""
        seen = set()
        failures = 0
        for ch in self._guesses:
            if ch not in self.word or ch in seen:
                failures += 1
            seen.add(ch)
        return failures

    @property
    def remaining_guesses(self):
        return MAX_FAILURES - self._failures

    @property
    def status(self):
        if all(ch in self._guessed for ch in self.word):
            return STATUS_WIN
        if self.remaining_guesses < 0:
            return STATUS_LOSE
        return STATUS_ONGOING

    # ------------------------------------------------------------------
    # Observers and the input.
    # ------------------------------------------------------------------

    def get_masked_word(self):
        return ''.join(
            ch if ch in self._guessed else '_' for ch in self.word
        )

    def get_status(self):
        return self.status

    def guess(self, char):
        if self.status != STATUS_ONGOING:
            raise ValueError("The game has already ended.")
        self._guesses.append(char)

